from jsonb_to_recordset($q$[{"id":4839,"materia":"sus","nivel":0,"enunciado":"Pela Lei nº 8.080/1990, a saúde é:","opcoes":["Um direito fundamental do ser humano, e o Estado deve prover as condições para seu pleno exercício","Responsabilidade exclusiva de cada pessoa","Um serviço garantido só a trabalhadores formais que contribuem para a Previdência Social","Um benefício opcional dos municípios"],"explicacao":"O dever do Estado não exclui o das pessoas, da família, das empresas e da sociedade."},{"id":4840,"materia":"sus","nivel":0,"enunciado":"Para ser Agente Comunitário de Saúde, a pessoa deve, entre outros requisitos:","opcoes":["Residir na área da comunidade em que vai atuar","Ter diploma de medicina","Morar em outro município, para manter a imparcialidade","Ter mais de 60 anos"],"explicacao":"O vínculo com a comunidade é essencial ao trabalho do ACS."},{"id":4841,"materia":"sus","nivel":0,"enunciado":"O telefone do SAMU, serviço de atendimento móvel de urgência, é o:","opcoes":["192","190","193","199"],"explicacao":"190 é a Polícia Militar; 193, os Bombeiros."},{"id":4842,"materia":"sus","nivel":0,"enunciado":"O Cartão Nacional de Saúde (Cartão SUS) serve para:","opcoes":["Identificar o usuário e registrar seus atendimentos no SUS","Pagar consultas","Comprar remédios com desconto em qualquer farmácia particular do país","Substituir o RG em qualquer situação"],"explicacao":"Pode ser obtido gratuitamente, inclusive pelo aplicativo Meu SUS Digital."},{"id":4843,"materia":"sus","nivel":0,"enunciado":"Entre as condicionalidades de saúde do Programa Bolsa Família estão:","opcoes":["Vacinação em dia das crianças, pré-natal das gestantes e acompanhamento nutricional","Exames de sangue mensais de toda a família em laboratórios credenciados","Consultas com especialista a cada semana","Cirurgias preventivas"],"explicacao":"O acompanhamento é feito pela atenção primária."},{"id":4844,"materia":"sus","nivel":0,"enunciado":"O Programa Saúde na Escola (PSE) articula ações entre:","opcoes":["Saúde e educação","Saúde e segurança pública","Educação e transporte","Saúde e turismo"],"explicacao":"Criado em 2007, atua nas escolas públicas."},{"id":4845,"materia":"sus","nivel":0,"enunciado":"A UPA 24h faz parte da:","opcoes":["Rede de Atenção às Urgências e Emergências","Rede de saúde bucal","Rede de vigilância sanitária de alimentos e bebidas","Rede de escolas técnicas"],"explicacao":"Atende casos de média complexidade, articulada com a APS e os hospitais."},{"id":4846,"materia":"sus","nivel":0,"enunciado":"O Consultório na Rua atende principalmente:","opcoes":["Pessoas em situação de rua","Turistas estrangeiros","Atletas profissionais","Moradores de condomínios fechados"],"explicacao":"Equipes multiprofissionais que vão até onde as pessoas estão."},{"id":4847,"materia":"sus","nivel":0,"enunciado":"Acupuntura, homeopatia e fitoterapia fazem parte da:","opcoes":["Política Nacional de Práticas Integrativas e Complementares (PNPIC)","Política Nacional de Urgências","Lei do Exercício da Enfermagem","Política Nacional de Saúde do Trabalhador e da Trabalhadora"],"explicacao":"Instituída em 2006 e ampliada depois."},{"id":4848,"materia":"sus","nivel":1,"enunciado":"O programa Melhor em Casa organiza a:","opcoes":["Atenção domiciliar no SUS","Construção de moradias populares","Entrega de cestas básicas","Reforma de hospitais"],"explicacao":"Na modalidade AD1, o cuidado em casa é feito pela atenção primária."},{"id":4849,"materia":"sus","nivel":1,"enunciado":"A Rede Alyne, lançada em 2024, reestruturou o cuidado:","opcoes":["Materno-infantil, com foco na redução da mortalidade materna","Odontológico","Oncológico de alta complexidade nos hospitais universitários","De saúde mental"],"explicacao":"Sucedeu a Rede Cegonha. Homenageia Alyne Pimentel, cuja morte levou o Brasil a ser condenado em um comitê da ONU."},{"id":4850,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Saúde Integral LGBT garante, entre outros pontos:","opcoes":["O uso do nome social no SUS","Atendimento separado em hospitais exclusivos","Proibição de acompanhantes","Cobrança diferenciada"],"explicacao":"Também combate a discriminação nos serviços."},{"id":4851,"materia":"sus","nivel":1,"enunciado":"Os Centros Especializados em Reabilitação (CER) fazem parte da rede de cuidados à:","opcoes":["Pessoa com deficiência","Gestante","Pessoa em situação de rua","Saúde do trabalhador rural"],"explicacao":"Oferecem reabilitação física, auditiva, visual e intelectual."},{"id":4852,"materia":"sus","nivel":1,"enunciado":"O programa Farmácia Popular do Brasil:","opcoes":["Oferece medicamentos gratuitos ou com desconto em farmácias credenciadas","Vende plano de saúde","Distribui apenas vitaminas e suplementos alimentares nas escolas","Só funciona em hospitais"],"explicacao":"Inclui remédios para hipertensão, diabetes e asma."},{"id":4853,"materia":"sus","nivel":1,"enunciado":"A Política Nacional de Atenção Integral à Saúde das Pessoas Privadas de Liberdade (PNAISP) garante:","opcoes":["O acesso das pessoas presas às ações e serviços do SUS","Atendimento só depois da soltura","Atendimento apenas por médicos particulares, pagos pela família","A criação de hospitais dentro dos tribunais"],"explicacao":"As equipes de atenção primária prisional fazem parte da política."},{"id":4854,"materia":"sus","nivel":1,"enunciado":"O programa Mais Médicos, criado em 2013, busca:","opcoes":["Levar médicos para regiões com falta de profissionais, especialmente na atenção primária","Fechar unidades básicas de saúde e concentrar médicos nos hospitais das capitais","Formar apenas cirurgiões","Substituir os enfermeiros"],"explicacao":"Também prevê ações de formação."},{"id":4855,"materia":"sus","nivel":2,"enunciado":"O VIGITEL é:","opcoes":["Um inquérito telefônico sobre fatores de risco e proteção para doenças crônicas nas capitais","Um sistema de notificação de acidentes de trabalho e de doenças ocupacionais nas indústrias","Um aplicativo de marcação de consultas","Um 